contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit `amount` into c from this contract, then call withdrawAll and check the invariant.
    // The function is payable only so the test runner can send ether to this test; but we will use the
    // parameter `amount` to forward funds to c. Ensure this contract has enough balance to forward.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Record c balance before deposit
        uint beforeC = address(c).balance;

        // Make a deposit of `amount` into c on behalf of this contract (msg.sender for c will be this contract)
        c.deposit{value: amount}();

        // After deposit, credit[this] should have increased by amount as observable by calling withdrawAll effects only
        // We can't read private mapping directly, but we can observe behavior of withdrawAll.

        // Record c balance before withdraw
        uint beforeWithdrawC = address(c).balance;
        // Record this contract balance before withdraw attempt
        uint beforeThis = address(this).balance;

        bool reverted;
        // Call withdrawAll and catch revert
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // If the call did not revert, then withdrawAll must have transferred exactly the depositted credit (amount)
        // from the contract to this contract, and set the caller's credit to zero — which we observe as the contract
        // losing `amount` and this contract gaining `amount`.
        // If it reverted, we accept that outcome as allowed.
        assert(reverted || (beforeWithdrawC == afterC + amount && afterThis == beforeThis + amount));
    }

    // Allow receiving ETH when c calls back (not expected, but safe)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an amount to deposit, then attempt withdrawAll
    // We will deposit 'amount' from this contract into c, then call withdrawAll and check the observable effects.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record contract balance of c before deposit
        uint balanceBefore = address(c).balance;
        // deposit amount into c
        c.deposit{value: amount}();
        // credit as seen via public getter after deposit
        uint creditAfterDeposit = c.credit(address(this));
        // record balance after deposit
        uint balanceAfterDeposit = address(c).balance;

        // Now try withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe credit and contract balance after withdraw attempt
        uint creditAfter = c.credit(address(this));
        uint balanceFinal = address(c).balance;

        // General rule:
        // If withdrawAll reverted, nothing else is required. Otherwise (not reverted):
        // 1) The caller's credit is zero after the call.
        // 2) The contract's balance decreased by at least the credited amount that was observed before the withdraw call (i.e., creditAfterDeposit).
        // We express decrease as: balanceFinal + creditAfterDeposit <= balanceAfterDeposit
        // The assert encodes the implication: if not reverted then both properties hold.
        assert(reverted || (creditAfter == 0 && balanceFinal + creditAfterDeposit <= balanceAfterDeposit));
    }

    // receive to accept ETH when c sends funds back to this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Deposit an amount into c, then call withdrawAll and check observable effects.
    // We cannot read the private mapping credit, so we observe balances only.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record c's balance before deposit
        uint cBalanceBefore = address(c).balance;
        // record this contract's balance before deposit
        uint selfBalanceBefore = address(this).balance;

        // deposit amount into c
        c.deposit{value: amount}();

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe balances after withdrawAll
        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;

        // If withdrawAll did not revert then:
        // - c's balance decreased by at least amount (it paid out at most the credited amount which is <= amount deposited by this test in this run)
        //   We use inequality: cBalanceBefore + amount >= cBalanceAfter
        // - this contract's balance did not increase by more than amount (it can only receive up to its credited amount)
        // - calling withdrawAll again from this contract (which would be a no-op if credit was cleared) must not further increase this contract's balance
        bool secondReverted;
        uint selfBalanceAfterSecond;
        if (!reverted) {
            // try a second withdrawAll to observe further effects
            try c.withdrawAll() {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            selfBalanceAfterSecond = address(this).balance;
        } else {
            // If first reverted, we don't require anything about balances other than leaving them as observed
            secondReverted = false;
            selfBalanceAfterSecond = selfBalanceAfter;
        }

        assert(
            reverted || (
                // c's balance decreased by at least the deposited amount
                cBalanceBefore + amount >= cBalanceAfter
                // this contract's balance did not increase by more than amount
                && selfBalanceAfter <= selfBalanceBefore + amount
                // and the second withdrawAll did not increase this contract's balance further
                && selfBalanceAfterSecond <= selfBalanceAfter
            )
        );
    }

    receive() external payable {}
}

