    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);
        // Make a deposit to create nonzero credit (could be zero if depositAmount==0)
        c.deposit{value: depositAmount}();
        // Read recorded credit via attempting to withdraw later: there is no direct getter, but we can infer by attempting withdraw and comparing balances.
        // Record balances before withdraw attempt
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool reverted;
        if (doWithdraw) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If not withdrawing, force reverted=false and do nothing
            reverted = false;
        }
        // Read balances after
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        // We assert a general invariant: if we performed withdraw (doWithdraw==true) and there was nonzero credit (depositAmount>0), then either the call reverted, or it succeeded and c's balance decreased by exactly the amount transferred to this contract and this contract's balance increased by that same amount; additionally the recorded credit for this caller must now be zero which is observable by that a subsequent withdrawAll would not transfer further funds (i.e., a second withdraw does not change balances).
        if (doWithdraw && depositAmount > 0) {
            // If reverted, nothing required except revert flag true
            if (reverted) {
                assert(reverted == true);
            } else {
                // call succeeded: check immediate balance movement equals some positive amount and equals depositAmount (since only this test caller made deposits)
                uint deltaC = beforeC - afterC;
                uint deltaThis = afterThis - beforeThis;
                // Now ensure they match and equal the deposited credit (depositAmount)
                // Also ensure a subsequent withdrawAll does not transfer additional funds
                uint beforeC2 = address(c).balance;
                uint beforeThis2 = address(this).balance;
