                    reverted2 = true;
                }
                uint afterC2 = address(c).balance;
                uint afterThis2 = address(this).balance;
                uint deltaC2 = beforeC2 - afterC2;
                uint deltaThis2 = afterThis2 - beforeThis2;
                assert(deltaC == deltaThis && deltaC == depositAmount && (!reverted2 ? (deltaC2 == 0 && deltaThis2 == 0) : true));
            }
        } else {
            // If we didn't attempt withdraw or depositAmount==0, just assert nothing surprising: balances reflect deposit when we didn't withdraw
            if (!doWithdraw) {
                // after should equal before plus deposit
                assert(afterC == beforeC);
            } else {
                // depositAmount==0 and we withdrew: then either reverted or no balance changes
                if (reverted) {
                    assert(reverted == true);
                } else {
                    assert(afterC == beforeC && afterThis == beforeThis);
                }
            }
        }
    }
    receive() external payable {}
}

